import html,json
ROOT=Path(__file__).resolve().parents[1]
cases=json.loads((ROOT/"data/case-studies.json").read_text(encoding="utf-8"))
fonts_path=ROOT/"assets/fonts-section.html"
if not fonts_path.exists():
    old=(ROOT/"index.html").read_text(encoding="utf-8")
    start=old.index('    <section class="shell section fonts-section"')
    end=old.find('    <section class="catalog-section',start)
    if end<0:end=old.index('</main>',start)
